.experience-controls { display: flex; align-items: center; gap: .55rem; }
.experience-controls button { display: inline-flex; align-items: center; justify-content: center; gap: .4rem; min-height: 36px; padding: 6px 0; border: 0; background: none; color: inherit; font: inherit; white-space: nowrap; cursor: var(--site-interactive-cursor, pointer); transition: opacity 160ms ease, transform 160ms ease; }
