.experience-frames button { min-width: 0; padding: 0 0 .75rem; border: 0; border-bottom: 1px solid transparent; border-radius: 0; background: none; text-align: left; color: var(--site-text-secondary); cursor: var(--site-interactive-cursor, pointer); transition: color 160ms ease, border-color 160ms ease; }
.experience-frames button[aria-pressed="true"] { color: var(--site-text-primary); border-color: currentColor; }
.experience-thumbnail { position: relative; display: block; overflow: hidden; opacity: .65; transition: opacity 160ms ease; }
.thumbnail-light { position: absolute; inset: 0; clip-path: inset(0 50% 0 0); }
