<template>
  <figure class="project-showcase" :class="{ 'is-keyboard-change': keyboardChange, 'is-contextual': contextual }" @click.stop @keydown.stop>
    <div :id="`${uid}-panel`" class="project-showcase-panel" :role="scene ? null : 'tabpanel'" :aria-labelledby="scene ? null : `${uid}-tab-${activeIndex}`">
      <button type="button" class="project-showcase-art image-enlarge" :aria-label="`Enlarge ${current.label}`" aria-haspopup="dialog" @click="openViewer">
        <AnimatedProjectArtwork v-if="current.motion" :key="current.motion" :composition="current.motion" :playback-rate="2" :fallback="current.src" :alt="current.alt" :paused="artPaused" :run="artRun" @complete="artFinished = true" @motion-available="artMotionAvailable = $event" />
        <template v-else><img v-for="(item, index) in scenes" :key="item.src" :src="item.src"
          :srcset="`${item.smallSrc} 800w, ${item.src} 1600w`"
          sizes="(max-width: 720px) 90vw, (max-width: 960px) 85vw, 960px"
          :width="item.width" :height="item.height"
          :alt="index === activeIndex ? item.alt : ''" :aria-hidden="index !== activeIndex"
          :class="{ 'is-active': index === activeIndex }" loading="lazy" decoding="async"></template>
      </button>
    </div>
    <div class="project-showcase-controls">
      <div v-if="!scene" class="project-showcase-tabs" :style="{ '--scene-count': scenes.length }" role="tablist" :aria-label="`${showcase.title} examples`" @keydown="onTabKey">
        <button v-for="(item, index) in scenes" :id="`${uid}-tab-${index}`" :key="item.src"
          type="button" role="tab" :aria-selected="index === activeIndex" :tabindex="index === activeIndex ? 0 : -1"
          :aria-controls="`${uid}-panel`" @click="select(index, $event.detail === 0)">
          <span class="project-showcase-thumbnail"><img :src="item.smallSrc" width="800" height="590" alt="" loading="lazy" decoding="async"></span>
          <span class="project-showcase-tab-label"><small aria-hidden="true">{{ String(index + 1).padStart(2, '0') }}</small>{{ item.label }}</span>
        </button>
      </div>
      <span v-else-if="!contextual" class="project-showcase-scene-label">{{ current.label }}</span>
      <div class="project-showcase-art-controls">
      <button v-if="current.motion && artMotionAvailable" type="button" class="project-showcase-transport" :aria-label="artFinished ? 'Replay illustration' : artPaused ? 'Play illustration' : 'Pause illustration'" @click="toggleArt">
        <svg viewBox="0 0 20 20" aria-hidden="true"><path v-if="artFinished" d="M4 7a6.5 6.5 0 1 1-.1 6M4 3v4h4"/><path v-else-if="artPaused" d="m7 4 8 6-8 6Z"/><path v-else d="M7 4v12M13 4v12"/></svg>
      </button>
      <button type="button" class="project-showcase-expand" :aria-label="`Enlarge ${current.label}`" aria-haspopup="dialog" @click="openViewer">
        <svg viewBox="0 0 20 20" aria-hidden="true"><path d="M12 3h5v5M17 3l-5.5 5.5M8 17H3v-5m0 5 5.5-5.5" /></svg>
      </button>
      </div>
    </div>
    <figcaption v-if="!contextual">{{ current.caption }}</figcaption>
    <Teleport to="body">
      <dialog ref="viewer" class="project-artwork-viewer" :aria-label="`${showcase.title} artwork`" @close="onClose" @click="closeOnBackdrop" @keydown="onViewerKey">
        <header class="project-artwork-viewer-head">
          <span>{{ showcase.title }}<small>{{ current.label }}</small></span>
          <div>
            <button type="button" aria-label="Close artwork" autofocus @click="closeViewer"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 5 10 10M15 5 5 15" /></svg></button>
          </div>
        </header>
        <div class="project-artwork-viewer-body">
          <img v-if="viewerOpen" :src="current.src" :width="current.width" :height="current.height" :alt="current.alt">
        </div>
        <footer class="project-artwork-viewer-foot">
          <p>{{ current.caption }}</p>
          <div v-if="scenes.length > 1">
            <button type="button" aria-label="Previous artwork" @click="step(-1)"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M16 10H4m5-5-5 5 5 5" /></svg></button>
            <span aria-live="polite">{{ activeIndex + 1 }} / {{ scenes.length }}</span>
            <button type="button" aria-label="Next artwork" @click="step(1)"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M4 10h12m-5-5 5 5-5 5" /></svg></button>
          </div>
        </footer>
      </dialog>
    </Teleport>
  </figure>
</template>

<script>
import AnimatedProjectArtwork from './AnimatedProjectArtwork.vue';
import { projectShowcases } from '../../data/projectShowcases';

export default {
  name: 'ProjectShowcase',
  components: { AnimatedProjectArtwork },
  props: {
    projectId: { type: String, required: true },
    // A case study can place individual compositions beside the relevant argument.
    scene: { type: String, default: '' },
    contextual: { type: Boolean, default: false },
  },
  data() {
    const showcase = projectShowcases[this.projectId];
    const activeIndex = this.scene ? 0 : Math.max(0, showcase.scenes.findIndex(item => item.label === showcase.defaultScene));
    return { activeIndex, keyboardChange: false, viewerOpen: false, artPaused: false, artFinished: false, artRun: 0, artMotionAvailable: false };
  },
  computed: {
    uid() { return `project-showcase-${this.$.uid}`; },
    showcase() { return projectShowcases[this.projectId]; },
    scenes() { return this.scene ? this.showcase.scenes.filter(item => item.label === this.scene) : this.showcase.scenes; },
    current() { return this.scenes[this.activeIndex] || this.scenes[0]; }
  },
  beforeUnmount() { if (this.viewerOpen) this.onClose(); },
  methods: {
    select(index, keyboard = false) { this.keyboardChange = keyboard; this.activeIndex = index; this.artFinished = false; this.artPaused = false; },
    toggleArt() { if (this.artFinished) { this.artRun += 1; this.artFinished = false; this.artPaused = false; } else this.artPaused = !this.artPaused; },
    step(direction) { this.select((this.activeIndex + direction + this.scenes.length) % this.scenes.length, true); },
    onTabKey(event) {
      if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
      event.preventDefault();
      if (event.key === 'Home') this.select(0, true);
      else if (event.key === 'End') this.select(this.scenes.length - 1, true);
      else this.step(event.key === 'ArrowRight' ? 1 : -1);
      this.$nextTick(() => this.$el.querySelector(`#${this.uid}-tab-${this.activeIndex}`)?.focus());
    },
    openViewer() {
      this._trigger = document.activeElement;
      this._bodyOverflow = document.body.style.overflow;
      this.viewerOpen = true;
      document.body.style.overflow = 'hidden';
      this.$refs.viewer.showModal();
    },
    closeViewer() { this.$refs.viewer.close(); },
    onClose() {
      if (!this.viewerOpen) return;
      this.viewerOpen = false;
      document.body.style.overflow = this._bodyOverflow || '';
      if (this._trigger?.isConnected) this._trigger.focus({ preventScroll: true });
    },
    closeOnBackdrop(event) { if (event.target === this.$refs.viewer) this.closeViewer(); },
    onViewerKey(event) {
      event.stopPropagation();
      if (['ArrowLeft', 'ArrowRight'].includes(event.key)) {
        event.preventDefault();
        this.step(event.key === 'ArrowRight' ? 1 : -1);
      }
    }
  }
};
</script>

